// The Files tab's explorer: the checkout's tree, with directories expanding in
// place under their rows the way an IDE draws it.
//
// Each directory's listing is its own `tree` record in the cache, the same one
// the sync layer re-lists when the checkout moves. Expanding a directory lists
// it — from the record when the cache holds one, and through `fs.tree`, written
// back to the record, when it does not (or when nobody else keeps this
// checkout's records true). Collapsing drops the watch and keeps the record.
// Which directories are expanded is UI state, remembered per checkout in its
// own record and painted from that record's readback like every other view.
//
// Pointer and key: on a fine pointer a click selects a file row (the keyboard
// selection) and a double-click opens it; on a coarse pointer a tap opens it.
// A click on a directory toggles it on both. Arrow keys move the selection and
// expand/collapse, Enter opens. The open file's row carries `.sel` on every
// paint; the keyboard selection is `.cursor` — two states, drawn differently.

import { mergeCachedRecordsTogether, readCached, recordWriteOf, subscribeCache } from "./localCache.js";
import { watchUiState } from "./localUiState.js";
import { ancestorsOf, fileTreeHtml, treeEdge, treeKeyMove, visibleTreeRows } from "./fileTreeModel.js";
import { registerSyncRead, registerSyncTree, syncPaneShown } from "./syncVisibleScopes.js";
import { appendDirectoryPage, directoryListing, directoryTouchedByHint, normalizedDirectoryHint } from "./directoryPages.js";

const heldRecord = (address) => (address ? readCached(address) : Promise.resolve(undefined));
const alwaysActive = () => true;
const DIRECTORY_PAGE_CAP = 8;
const heldPageCount = (listing) => {
  // Earlier paged caches kept entries but no depth; infer their 100-row pages.
  const inferred = Math.ceil((listing?.entries?.length || 0) / 100);
  return Math.min(DIRECTORY_PAGE_CAP, Math.max(1, Math.trunc(Number(listing?.loaded_pages) || inferred)));
};
const countedListing = (listing, count) => count > 1 ? { ...listing, loaded_pages: Math.min(count, DIRECTORY_PAGE_CAP) } : listing;
const containsEntry = (listing, name) => listing?.entries?.some((entry) => entry.name === name);
const sameDirectoryKey = (left, right) => left.name === right.name
  && (left.kind === "dir") === (right.kind === "dir");
const containsHeldTail = (listing, tail) => listing.entries.some((entry) => sameDirectoryKey(entry, tail));
const needsHeldTail = (listing, tail, count, budget) => Boolean(tail && listing.next_cursor)
  && count < budget && !containsHeldTail(listing, tail);
const mergedListing = (held, arriving, cursor) => cursor
  ? countedListing(appendDirectoryPage(held, arriving, cursor), heldPageCount(held) + 1) : arriving;

const readExpanded = (value) =>
  new Set((Array.isArray(value?.expanded) ? value.expanded : []).filter((dir) => typeof dir === "string" && dir));

/** Whether every directory above `dir` is expanded, so its own listing shows. */
const reachable = (expanded, dir) => ancestorsOf(dir).every((above) => expanded.has(above));

const rowsIn = (listEl) => [...listEl.querySelectorAll(".frow[data-path]")];

/** Mark the open file and the keyboard selection on the rows already drawn.
 *  In place rather than a repaint: a double-click's two clicks must land on the
 *  same element, and a repaint between them would swap it. */
const markRows = (listEl, openPath, cursorPath) => {
  const rows = rowsIn(listEl);
  const focusRow = rows.find((row) => row.dataset.path === cursorPath) || rows[0];
  rows.forEach((row) => {
    const open = row.dataset.path === openPath;
    const cursor = row.dataset.path === cursorPath;
    row.classList.toggle("sel", open);
    row.classList.toggle("cursor", cursor);
    if (open) row.setAttribute("aria-current", "true");
    else row.removeAttribute("aria-current");
    row.setAttribute("aria-selected", String(cursor));
    row.tabIndex = row === focusRow ? 0 : -1;
  });
};

/**
 * mountFileTree(listEl, options) — draw the explorer into `listEl`.
 *
 * - `listingAddress(dir)`: the cache address of a directory's listing, or null
 *   for a mount that saves nothing;
 * - `stateAddress`: the UI-state address for the expanded set, or null;
 * - `readsForItself()`: whether a held listing is only a seed (nobody else
 *   keeps this checkout's records true), so it is painted and read anyway;
 * - `listDirectory(dir)`: the `fs.tree` read;
 * - `finePointer()`: whether a click selects rather than opens;
 * - `onOpen(path)`: open a file;
 * - `baseDepth`: how many levels the rows stand under (1 under a workspace's
 *   root row, core/fileRoots.js);
 * - `onEdge(direction)`: the arrows walked out of the rows ("up", "down",
 *   "out"); a tree with nothing around it keeps them, as it always has.
 *
 * Returns { ready, setOpenPath, reveal, relist, dispose }.
 */
export function mountFileTree(listEl, { listingAddress, stateAddress = null, readsForItself, listDirectory, finePointer, onOpen, baseDepth = 0, onEdge = null, keepHeldOnError = false, keepReadingPlace = (paint) => paint(), watchDirectory = () => null }) {
  let disposed = false;
  const listings = new Map();
  let expanded = new Set();
  let openPath = null;
  let cursorPath = null;
  let rows = [];
  const watches = new Map(); // shown directory → unwatch
  const requests = new Map(); // shown directory → the read its paints still speak for
  const paging = new Map();
  const loading = new Map();

  const focusCursor = (options) => {
    const row = rowsIn(listEl).find((candidate) => candidate.dataset.path === cursorPath);
    if (options) row?.focus(options);
    else row?.focus();
  };

  const paint = () => keepReadingPlace(() => {
    if (disposed) return;
    if (!listings.has("")) {
      listEl.innerHTML = "";
      return;
    }
    const hadFocus = listEl.contains(document.activeElement);
    const scrollTop = listEl.scrollTop;
    rows = visibleTreeRows(listings, expanded, "", baseDepth);
    listEl.innerHTML = fileTreeHtml(rows, { openPath, cursorPath });
    listEl.scrollTop = scrollTop;
    if (hadFocus) focusCursor({ preventScroll: true });
  });

  const shown = (dir) => !dir || (expanded.has(dir) && reachable(expanded, dir));
  const unregisterSyncTree = registerSyncTree(
    () => listingAddress(""), () => ["", ...expanded].filter(shown),
    () => !disposed && syncPaneShown(listEl),
  );
  const stillListing = (dir, request, active = alwaysActive) => active() && !disposed && requests.get(dir) === request && shown(dir);

  const takeListing = (dir, listing) => {
    listings.set(dir, listing);
    paint();
  };

  const reread = async (dir, request) => {
    if (!stillListing(dir, request)) return;
    const held = (await heldRecord(listingAddress(dir)))?.value;
    if (stillListing(dir, request) && held) takeListing(dir, held);
  };

  const askMachine = async (dir, cursor = null) => {
    try {
      const answer = cursor ? await listDirectory(dir, { cursor }) : await listDirectory(dir);
      return directoryListing(answer, dir);
    } catch (error) {
      return { error: error?.message || "error", error_code: error?.code || error?.error_code };
    }
  };

  /** A directory nothing holds a listing for (or nothing else keeps true):
   *  ask the machine, and write the answer through so the paint comes from the
   *  record — unless a newer write landed while the question was out. */
  const showListingError = (dir, listing, quiet) => {
    if (!quiet && (!keepHeldOnError || !listings.has(dir))) takeListing(dir, listing);
  };

  const recoverRefusedCursor = async (dir, previousWrite, active, listing) => {
    if (listing.error_code !== "invalid_params") return false;
    if (!syncPaneShown(listEl) || !active()) return true;
    const held = await heldRecord(listingAddress(dir));
    if (recordWriteOf(held) === previousWrite) await load(dir, true, active);
    return true;
  };

  const readHeldWindow = async (dir, request, active, first, previous) => {
    let listing = first, count = 1;
    const tail = previous?.entries?.at(-1), budget = 1;
    while (needsHeldTail(listing, tail, count, budget)) {
      if (!stillListing(dir, request, active)) return null;
      const page = await askMachine(dir, listing.next_cursor);
      if (page.error) return page;
      listing = appendDirectoryPage(listing, page, listing.next_cursor);
      count += 1;
    }
    return countedListing(listing, count);
  };

  const readListingWindow = async (dir, request, active, cursor, previous) => {
    const first = await askMachine(dir, cursor);
    return cursor || first.error ? first : readHeldWindow(dir, request, active, first, previous);
  };

  const handleListingError = async (dir, previousWrite, active, listing, cursor, quiet) => {
    if (cursor && await recoverRefusedCursor(dir, previousWrite, active, listing)) return;
    showListingError(dir, listing, quiet);
  };

  const listFromMachine = async (dir, request, previousWrite, quiet = false, active = alwaysActive, cursor = null, previous = null) => {
    if (!stillListing(dir, request, active)) return;
    const listing = await readListingWindow(dir, request, active, cursor, previous);
    if (!listing || !stillListing(dir, request, active)) return;
    const address = listingAddress(dir);
    // An error is this mount's news, not the directory's: it never replaces a record.
    if (listing.error) return handleListingError(dir, previousWrite, active, listing, cursor, quiet);
    if (!address) return takeListing(dir, mergedListing(listings.get(dir), listing, cursor));
    await mergeCachedRecordsTogether([address], ([record]) => [
      stillListing(dir, request, active) && recordWriteOf(record) === previousWrite
        ? mergedListing(record?.value, listing, cursor) : null,
    ]);
  };

  const watch = (dir, request) => {
    watches.get(dir)?.();
    const address = listingAddress(dir);
    watches.set(dir, address ? subscribeCache(address, () => void reread(dir, request)) : () => {});
  };

  const beginListing = (dir) => {
    const request = (requests.get(dir) || 0) + 1;
    requests.set(dir, request);
    watch(dir, request);
    return request;
  };

  const cachedListingSuffices = (listing, force, fulfilled) =>
    !listing.stale && (fulfilled || (!force && !readsForItself()));

  const loadListing = async (dir, force = false, active = alwaysActive, fulfilled = false) => {
    if (!active()) return;
    const request = beginListing(dir);
    const record = await heldRecord(listingAddress(dir));
    if (!stillListing(dir, request, active)) return;
    if (record?.value) {
      takeListing(dir, record.value);
      if (cachedListingSuffices(record.value, force, fulfilled)) return;
    }
    await listFromMachine(dir, request, recordWriteOf(record), force, active, null, record?.value);
  };
  const load = (dir, ...options) => {
    const reading = loadListing(dir, ...options);
    loading.set(dir, reading);
    const done = () => { if (loading.get(dir) === reading) loading.delete(dir); };
    void reading.then(done, done);
    return reading;
  };

  const readMore = async (dir) => {
    const cursor = listings.get(dir)?.next_cursor;
    if (!cursor || !shown(dir)) return;
    const request = beginListing(dir);
    const record = await heldRecord(listingAddress(dir));
    if (record && record.value?.next_cursor !== cursor) return;
    await listFromMachine(dir, request, recordWriteOf(record), true, alwaysActive, cursor, record?.value);
  };
  const more = (dir) => {
    if (paging.has(dir)) return paging.get(dir);
    const pending = readMore(dir).finally(() => { if (paging.get(dir) === pending) paging.delete(dir); });
    paging.set(dir, pending);
    return pending;
  };

  const canRevealMore = (dir) => !disposed && shown(dir) && syncPaneShown(listEl)
    && Boolean(listings.get(dir)?.next_cursor);
  const revealInDirectory = async (dir, name, remaining) => {
    await loading.get(dir);
    if (!listings.has(dir)) await load(dir);
    while (remaining > 0 && !containsEntry(listings.get(dir), name)) {
      if (!canRevealMore(dir)) break;
      await more(dir);
      await reread(dir, requests.get(dir));
      remaining -= 1;
    }
    return remaining;
  };

  const revealPath = async (path) => {
    await ready;
    if (disposed) return;
    const ancestors = ancestorsOf(path), missing = ancestors.filter((dir) => !expanded.has(dir));
    if (missing.length) await commitExpanded(new Set([...expanded, ...missing]));
    let remaining = DIRECTORY_PAGE_CAP;
    for (const dir of ["", ...ancestors]) {
      const name = (dir ? path.slice(dir.length + 1) : path).split("/")[0];
      remaining = await revealInDirectory(dir, name, remaining);
      if (!containsEntry(listings.get(dir), name)) break;
    }
  };

  const hintDirectories = (files) => ["", ...expanded].filter(shown)
    .filter((dir) => directoryTouchedByHint(dir, files));
  const refreshShown = (active = alwaysActive, { files, fulfilledDirectories = [] } = {}) => {
    const directories = files ? hintDirectories(normalizedDirectoryHint(files)) : ["", ...expanded].filter(shown);
    return Promise.all(directories.map((dir) => load(dir, true, active, fulfilledDirectories.includes(dir))));
  };
  const unregisterSyncRead = registerSyncRead(
    () => listingAddress(""), refreshShown,
    () => !disposed && syncPaneShown(listEl),
  );
  const directoryWatcher = watchDirectory(() => !disposed && syncPaneShown(listEl), (active) => refreshShown(active));

  const stop = (dir) => {
    watches.get(dir)?.();
    watches.delete(dir);
    requests.set(dir, (requests.get(dir) || 0) + 1);
  };

  /** Paint an expanded set: watch and list every directory it shows, drop the
   *  watch on every one it no longer shows (its record stays). */
  const applyExpanded = (next) => {
    expanded = next;
    [...watches.keys()].filter((dir) => !shown(dir)).forEach(stop);
    [...expanded].filter((dir) => shown(dir) && !watches.has(dir)).forEach((dir) => void load(dir));
    paint();
  };

  const record = stateAddress ? watchUiState(stateAddress, (value) => applyExpanded(readExpanded(value))) : null;
  const ready = Promise.resolve(record?.ready).catch(() => undefined);
  const commitExpanded = (next) =>
    record ? record.write({ expanded: [...next] }) : applyExpanded(next);

  const setExpanded = (dir, open) => {
    const next = new Set(expanded);
    if (open) next.add(dir);
    else next.delete(dir);
    return commitExpanded(next);
  };

  const setCursor = (path, { focus = false } = {}) => {
    cursorPath = path;
    markRows(listEl, openPath, cursorPath);
    if (focus) focusCursor();
  };

  const KEY_MOVES = {
    cursor: (path) => setCursor(path, { focus: true }),
    expand: (dir) => void setExpanded(dir, true),
    collapse: (dir) => void setExpanded(dir, false),
    open: (path) => onOpen(path),
  };

  const CLICKS = {
    // The second click of a double-click is not a second toggle: a folder
    // double-clicked open stays open.
    dir: (path, event) => {
      if (event.detail > 1 && finePointer()) return;
      void setExpanded(path, !expanded.has(path));
    },
    file: (path) => {
      if (!finePointer()) onOpen(path);
    },
  };

  const rowOf = (event) => event.target.closest?.(".frow[data-path]");

  const onClick = (event) => {
    const continuation = event.target.closest?.("[data-tree-more]");
    if (continuation) { void more(continuation.dataset.treeMore); return; }
    const row = rowOf(event);
    if (!row) return;
    setCursor(row.dataset.path);
    CLICKS[row.dataset.kind]?.(row.dataset.path, event);
  };

  const onDoubleClick = (event) => {
    const row = rowOf(event);
    if (row?.dataset.kind === "file" && finePointer()) onOpen(row.dataset.path);
  };

  const onKeyDown = (event) => {
    if (event.target.closest?.("[data-tree-more]")) return;
    const edge = onEdge && treeEdge(rows, cursorPath, event.key);
    if (edge) {
      event.preventDefault();
      onEdge(edge);
      return;
    }
    const move = treeKeyMove(rows, cursorPath, event.key);
    if (!move) return;
    event.preventDefault();
    Object.entries(move).forEach(([kind, path]) => KEY_MOVES[kind](path));
  };

  // Tab landing on a row makes it the selection the arrows move from.
  const onFocusIn = (event) => {
    const row = rowOf(event);
    if (row && row.dataset.path !== cursorPath) setCursor(row.dataset.path);
  };

  listEl.addEventListener("click", onClick);
  listEl.addEventListener("dblclick", onDoubleClick);
  listEl.addEventListener("keydown", onKeyDown);
  listEl.addEventListener("focusin", onFocusIn);
  void load("");

  return {
    ready,
    more,
    setVisible: () => directoryWatcher?.setVisible?.(),
    invalidate: (files, active = alwaysActive) => active() && syncPaneShown(listEl) ? refreshShown(active, { files }) : Promise.resolve(),
    /** The file in the preview: highlighted wherever its row is drawn, and
     *  where the keyboard selection moves to. */
    setOpenPath(path) {
      openPath = path;
      if (path) cursorPath = path;
      markRows(listEl, openPath, cursorPath);
    },
    /** Put the keyboard on the selection (or the first row), for the roots
     *  around this tree handing the arrows back. False when nothing is drawn. */
    focus() {
      const row = rowsIn(listEl).find((candidate) => candidate.tabIndex === 0);
      row?.focus();
      return Boolean(row);
    },
    /** Put the keyboard on the last row drawn. */
    focusLast() {
      const row = rowsIn(listEl).at(-1);
      if (row) setCursor(row.dataset.path, { focus: true });
      return Boolean(row);
    },
    /** Expand every directory above `path`, so its row is drawn. */
    reveal: revealPath,
    /** Read every shown directory again — the scope under the tree moved. */
    relist(paths = null) {
      ["", ...expanded].filter((dir) => shown(dir) && (!paths || !dir || paths.some((path) => path === dir || path.startsWith(`${dir}/`))))
        .forEach((dir) => void load(dir));
    },
    dispose() {
      disposed = true;
      unregisterSyncTree();
      unregisterSyncRead();
      directoryWatcher?.dispose();
      [...watches.keys()].forEach(stop);
      record?.dispose();
      listEl.removeEventListener("click", onClick);
      listEl.removeEventListener("dblclick", onDoubleClick);
      listEl.removeEventListener("keydown", onKeyDown);
      listEl.removeEventListener("focusin", onFocusIn);
    },
  };
}
